var marks=new[]{"WF-GF-N-S000-0","WF-FF-S-S000-0","SF-FJ1-01-TIMBER-01","RT-T5-01-W0"};return new FilteredElementCollector(document).OfClass(typeof(FamilyInstance)).Cast<FamilyInstance>().Where(e=>marks.Contains(e.get_Parameter(BuiltInParameter.ALL_MODEL_MARK)?.AsString())).Select(e=>{var box=e.get_BoundingBox(null);return new{mark=e.get_Parameter(BuiltInParameter.ALL_MODEL_MARK).AsString(),type=e.Symbol.Name,box=new[]{(box.Max.X-box.Min.X)*304.8,(box.Max.Y-box.Min.Y)*304.8,(box.Max.Z-box.Min.Z)*304.8},min=new[]{box.Min.X*304.8,box.Min.Y*304.8,box.Min.Z*304.8},bend=e.get_Parameter(BuiltInParameter.STRUCTURAL_BEND_DIR_ANGLE).AsDouble()};}).ToArray();
